/**
 * Checks if a JSX attribute is dangerous.
 * @param name - Name of the attribute to check.
 * @returns Whether or not the attribute is dangerous.
 */
function isDangerous(name: string) {
    return has(DANGEROUS_PROPERTIES, name);
